// Frame catalog (generated by models-src/build_frames.py) grouped by model.
const BASE = import.meta.env.BASE_URL;

export const CATEGORIES = [
  ["all", "All frames"], ["round", "Round"], ["square", "Square"], ["rectangle", "Rectangle"],
  ["cat-eye", "Cat-eye"], ["oval", "Oval"], ["aviator", "Aviator"], ["browline", "Browline"],
  ["geometric", "Geometric"],
];

export async function loadCatalog() {
  const [cat, fin] = await Promise.all([
    fetch(`${BASE}models/frames/catalog.json`).then((r) => r.json()),
    fetch(`${BASE}models/finishes.json`).then((r) => r.json()),
  ]);
  const models = new Map();
  for (const v of cat.frames) {
    let m = models.get(v.model_id);
    if (!m) {
      m = { id: v.model_id, name: v.name, style: v.style, construction: v.construction,
        preview: `${BASE}${v.preview}`, finishes: v.finishes, defaultFinish: v.finish,
        defaultLens: v.lens, faceShapes: v.face_shapes, sizes: {} };
      models.set(v.model_id, m);
    }
    m.sizes[v.size] = v;
  }
  return { models: [...models.values()], finishes: fin };
}

export function filterModels(models, { category = "all", query = "", recommended = [] } = {}) {
  const q = query.trim().toLowerCase();
  const list = models.filter((m) =>
    (category === "all" || m.style === category || (category === "match" && recommended.includes(m.id))) &&
    (!q || `${m.name} ${m.style} ${m.construction}`.toLowerCase().includes(q)));
  // matches are shown best first
  if (category === "match") list.sort((x, y) => recommended.indexOf(x.id) - recommended.indexOf(y.id));
  return list;
}
